<?php require_once '../../config/conexion.php'; $anio=(int)($_GET['anio']??date('Y')); $s=$conn->prepare("SELECT MONTH(fecha) mes,COUNT(*) registros,COALESCE(SUM(galones),0) galones,COALESCE(SUM(total),0) total FROM combustible_despachos WHERE YEAR(fecha)=? GROUP BY MONTH(fecha) ORDER BY mes");$s->bind_param('i',$anio);$s->execute();$res=$s->get_result(); ?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte anual</title></head><body style="font-family:Arial;padding:30px"><a href="dashboard.php">← Combustible</a><h1>Reporte anual</h1><form><input type="number" name="anio" value="<?=$anio?>"><button>Consultar</button></form><table border="1" cellpadding="8" cellspacing="0"><tr><th>Mes</th><th>Despachos</th><th>Galones</th><th>Total</th></tr><?php while($r=$res->fetch_assoc()): ?><tr><td><?=$r['mes']?></td><td><?=$r['registros']?></td><td><?=number_format($r['galones'],2)?></td><td>Q <?=number_format($r['total'],2)?></td></tr><?php endwhile; ?></table></body></html>
